# export_tree.py
# Trains the final decision tree (relative features) on ALL sessions and
# writes it as plain C code for the Arduino sketch.

import os

import numpy as np

from load_data import load_sessions
from train_eval import RELATIVE_FEATURES, add_features, make_tree

OUT_DIR = os.path.join(os.path.dirname(__file__), "..", "platform", "arduino",
                       "sentinela_arduino", "src", "core")

HEADER_TEMPLATE = """// classifier.h
// GENERATED by tools/export_tree.py. Do not edit by hand.

#ifndef CLASSIFIER_H
#define CLASSIFIER_H

#ifdef __cplusplus
extern "C" {
#endif

// Returns 1 if the sliding window looks anomalous, 0 otherwise.
// The inputs are computed from the sliding window by the caller:
//   stddev: standard deviation of the window
//   delta:  newest reading minus the window mean
int classifier_predict(@SIGNATURE@);

#ifdef __cplusplus
}
#endif

#endif // CLASSIFIER_H
"""

SOURCE_TEMPLATE = """// classifier.c
// GENERATED by tools/export_tree.py from a decision tree trained on the
// labeled sessions in /data. Do not edit by hand: re-run the script.

#include "classifier.h"

int classifier_predict(@SIGNATURE@) {
@BODY@
}
"""


def tree_to_c(tree, feature_names):
    t = tree.tree_
    used = set()

    def predicted_class(node):
        return int(np.argmax(t.value[node][0]))

    def constant_class(node):
        # Class returned by every path under this node, or None if mixed.
        if t.children_left[node] == -1:
            return predicted_class(node)
        left = constant_class(t.children_left[node])
        right = constant_class(t.children_right[node])
        return left if left is not None and left == right else None

    def emit(node, level):
        pad = "    " * level
        same = constant_class(node)
        if same is not None:
            return [f"{pad}return {same};"]
        name = feature_names[t.feature[node]]
        used.add(name)
        lines = [f"{pad}if ({name} <= {t.threshold[node]:.2f}f) {{"]
        lines += emit(t.children_left[node], level + 1)
        lines.append(f"{pad}}} else {{")
        lines += emit(t.children_right[node], level + 1)
        lines.append(f"{pad}}}")
        return lines

    body = "\n".join(emit(0, 1))
    params = [n for n in feature_names if n in used]
    return body, params


def main():
    data = add_features(load_sessions())
    tree = make_tree().fit(data[RELATIVE_FEATURES], data["label"])
    body, params = tree_to_c(tree, RELATIVE_FEATURES)
    signature = ", ".join(f"float {p}" for p in params) or "void"

    os.makedirs(OUT_DIR, exist_ok=True)
    with open(os.path.join(OUT_DIR, "classifier.h"), "w") as f:
        f.write(HEADER_TEMPLATE.replace("@SIGNATURE@", signature))
    with open(os.path.join(OUT_DIR, "classifier.c"), "w") as f:
        f.write(SOURCE_TEMPLATE.replace("@SIGNATURE@", signature)
                .replace("@BODY@", body))

    print(f"\nWrote classifier.h and classifier.c to {os.path.abspath(OUT_DIR)}\n")
    print(f"int classifier_predict({signature}) {{")
    print(body)
    print("}")


if __name__ == "__main__":
    main()